// ═══════════════════════════════════════════════════════
// GLOBAL CONFIG — preview-pay. Keys injected by scripts/deploy-workflow.mjs.
// ═══════════════════════════════════════════════════════
return [{ json: {
  SUPABASE_URL:         'https://nexkairsedqtczievxpa.supabase.co',
  SUPABASE_SERVICE_KEY: 'YOUR_SUPABASE_SERVICE_ROLE_KEY',
  // #56 — verifies the Telegram WebApp initData signature (reused from form-submit).
  TELEGRAM_BOT_TOKEN:   'YOUR_TELEGRAM_BOT_TOKEN',
  // #56 dev/web-fallback escape hatch, OFF in prod. Flip to 'true' locally only.
  ALLOW_UNVERIFIED_UID: 'false',
  // Private bucket holding the full PDF (migration 029, service-role only).
  BUCKET:               'generated-documents',
  // Signed-URL TTL (A3 = 24h). Re-mint allowed while the case is alive.
  SIGNED_URL_TTL:       '86400',
}}];

// ═══════════════════════════════════════════════════════
// Verify initData — GENERATED by scripts/build-preview-pay.mjs
// Edit n8n/templates/verify-init-data.js and re-run this script.
// ═══════════════════════════════════════════════════════

// initData HMAC verification (mirror: n8n/templates/verify-init-data.js)
/**
 * verify-init-data.js
 * n8n Code Node — verifies the signed Telegram WebApp `initData` string.
 *
 * Implements Telegram's official Mini App validation algorithm (NOT the
 * separate Login Widget algorithm, which uses a different secret derivation):
 *   secret_key = HMAC_SHA256(key="WebAppData", message=bot_token)
 *   hash       = HMAC_SHA256(key=secret_key,    message=data_check_string)
 * where data_check_string is every received field except `hash`, formatted
 * as "key=value" lines sorted alphabetically by key and joined with "\n".
 *
 * Without this check, a client can send an arbitrary `user_id` (#56) and
 * have a document generated/sent under someone else's identity — including
 * by simply omitting `initData`, which is why `resolveSubmission()` below
 * rejects a missing signature by default rather than falling back to the
 * raw `user_id` unconditionally.
 *
 * Query string is parsed by hand (split/decodeURIComponent) instead of the
 * `URLSearchParams` global — n8n's Code node sandbox does not expose it
 * (confirmed live: `ReferenceError: URLSearchParams is not defined`), even
 * though `require('crypto')` and `Buffer` are available.
 *
 * n8n entry point (paste into Code Node):
 *   const botToken = $('Global Config').first().json.TELEGRAM_BOT_TOKEN;
 *   const allowUnverified = $('Global Config').first().json.ALLOW_UNVERIFIED_UID === 'true';
 *   const result = resolveSubmission(init_data, user_id, botToken, { allowUnverified });
 */

const crypto = require('crypto');

function parseQueryString(qs) {
  const out = {};
  for (const pair of qs.split('&')) {
    if (!pair) continue;
    const eq = pair.indexOf('=');
    const rawKey = eq === -1 ? pair : pair.slice(0, eq);
    const rawValue = eq === -1 ? '' : pair.slice(eq + 1);
    const key = decodeURIComponent(rawKey.replace(/\+/g, ' '));
    const value = decodeURIComponent(rawValue.replace(/\+/g, ' '));
    out[key] = value;
  }
  return out;
}

/**
 * @param {string} initData - raw `Telegram.WebApp.initData` query string
 * @param {string} botToken - the bot's token (secret)
 * @param {{ maxAgeSeconds?: number }} [options] - maxAgeSeconds: replay window, default 24h
 * @returns {{ valid: boolean, reason?: string, user?: { id: number, first_name?: string, [k: string]: any } }}
 */
function verifyInitData(initData, botToken, options) {
  const maxAgeSeconds = options && options.maxAgeSeconds != null ? options.maxAgeSeconds : 86400;

  if (!initData) return { valid: false, reason: 'missing' };
  if (!botToken) return { valid: false, reason: 'no_bot_token' };

  let params;
  try {
    params = parseQueryString(initData);
  } catch (_) {
    return { valid: false, reason: 'malformed' };
  }

  const hash = params.hash;
  if (!hash) return { valid: false, reason: 'missing_hash' };

  const pairs = [];
  for (const key of Object.keys(params)) {
    if (key === 'hash') continue;
    pairs.push(key + '=' + params[key]);
  }
  pairs.sort();
  const dataCheckString = pairs.join('\n');

  const secretKey = crypto.createHmac('sha256', 'WebAppData').update(botToken).digest();
  const computedHash = crypto.createHmac('sha256', secretKey).update(dataCheckString).digest('hex');

  const computedBuf = Buffer.from(computedHash, 'hex');
  const givenBuf = Buffer.from(hash, 'hex');
  if (computedBuf.length !== givenBuf.length || !crypto.timingSafeEqual(computedBuf, givenBuf)) {
    return { valid: false, reason: 'bad_signature' };
  }

  const authDate = Number(params.auth_date);
  if (!authDate) return { valid: false, reason: 'missing_auth_date' };
  const ageSeconds = Date.now() / 1000 - authDate;
  if (ageSeconds > maxAgeSeconds) return { valid: false, reason: 'expired' };

  const userRaw = params.user;
  let user = null;
  if (userRaw) {
    try {
      user = JSON.parse(userRaw);
    } catch (_) {
      return { valid: false, reason: 'malformed_user' };
    }
  }
  if (!user || !user.id) return { valid: false, reason: 'missing_user' };

  return { valid: true, user };
}

/**
 * Decides whether a form-submit request is trustworthy enough to persist.
 *
 * A present-but-invalid signature is always a hard reject — a real Telegram
 * WebApp client signs correctly, so this means tampering or a bot-token
 * misconfig (fail closed). A missing `initData` is ALSO rejected by default:
 * omitting it entirely is the trivial way to bypass signature checking and
 * is exactly the spoofing vector #56 was opened for (an attacker doesn't
 * need to forge a hash if the server accepts requests with no signature at
 * all). The dev/web-fallback path the #56 checklist asks to keep is only
 * reachable when a server-side flag explicitly opts into it — never via
 * anything the client can control.
 *
 * @param {string} initData - raw `Telegram.WebApp.initData`, or falsy if absent
 * @param {string|number} userId - client-supplied `user_id` from the request body
 * @param {string} botToken - the bot's token (secret)
 * @param {{ allowUnverified?: boolean, maxAgeSeconds?: number }} [options]
 * @returns {{ ok: boolean, userId?: string, uidVerified?: boolean, error?: string, reason?: string }}
 */
function resolveSubmission(initData, userId, botToken, options) {
  const allowUnverified = !!(options && options.allowUnverified);

  if (initData) {
    const verification = verifyInitData(initData, botToken, options);
    if (!verification.valid) {
      return { ok: false, error: 'invalid_init_data', reason: verification.reason };
    }
    return { ok: true, userId: String(verification.user.id), uidVerified: true };
  }

  if (allowUnverified) {
    return { ok: true, userId: String(userId), uidVerified: false };
  }

  return { ok: false, error: 'missing_init_data' };
}

// n8n entry point:
const body = $('Webhook').first().json.body || {};
const { case_id, user_id, init_data, deliver_to_bot } = body;

if (!case_id) {
  return [{ json: { _ok: false, _error: 'missing_case_id' } }];
}

const botToken = $('Global Config').first().json.TELEGRAM_BOT_TOKEN;
const allowUnverified = $('Global Config').first().json.ALLOW_UNVERIFIED_UID === 'true';
const resolution = resolveSubmission(init_data, user_id, botToken, { allowUnverified });
if (!resolution.ok) {
  console.log('[preview-pay] auth rejected:', resolution.error, resolution.reason || '');
  return [{ json: { _ok: false, _error: resolution.error, _reason: resolution.reason || null } }];
}

return [{ json: {
  _ok: true,
  _user_id: resolution.userId,
  _case_id: String(case_id),
  _deliver_to_bot: deliver_to_bot === true,
} }];

// ═══════════════════════════════════════════════════════
// Assert & Decide — GENERATED by scripts/build-preview-pay.mjs
// Owner + ready gate. NEVER returns _ok:true unless a full document exists and the
// caller owns the case; the paid-flip downstream is reachable ONLY via _ok:true.
// ═══════════════════════════════════════════════════════

const ctx = $('Verify initData').first().json;
const rows = $('Get Case').all().map((i) => i.json).filter((r) => r && r.id != null);
const c = rows[0] || null;
const nowIso = new Date().toISOString();

// Resolve the verified Telegram id → profile UUID via the identities table
// (form-submit stores cases.user_id = identities.user_id, NOT the raw telegram id).
const idents = $('Get Identity').all().map((i) => i.json).filter((r) => r && r.user_id);
const ownerUuid = idents[0] ? idents[0].user_id : null;

// Case must exist.
if (!c) {
  return [{ json: { _ok: false, _error: 'case_not_found' } }];
}
// Owner check: the verified Telegram id must resolve to the profile that owns the case.
if (!ownerUuid || String(c.user_id) !== String(ownerUuid)) {
  return [{ json: { _ok: false, _error: 'not_owner' } }];
}
// Ready check: a full document must be parked AND status must allow payment.
// generating / failed / missing doc_storage_path → refuse, paid stays false.
const ready = !!c.doc_storage_path && (c.status === 'preview_ready' || c.status === 'paid');
if (!ready) {
  return [{ json: { _ok: false, _error: 'not_ready', _status: c.status || null } }];
}

// Idempotent flip: never overwrite paid_at on an already-paid case (re-mint only).
const alreadyPaid = c.paid === true;
const patch = alreadyPaid
  ? { paid: true, status: 'paid' }
  : { paid: true, status: 'paid', paid_at: nowIso };

return [{ json: {
  _ok: true,
  _case_id: String(c.id),
  _storage_path: c.doc_storage_path,
  _user_id: String(ctx._user_id),
  _deliver: ctx._deliver_to_bot === true,
  _already_paid: alreadyPaid,
  _patch_body: patch,
} }];

// ═══════════════════════════════════════════════════════
// Build Response — GENERATED by scripts/build-preview-pay.mjs
// ═══════════════════════════════════════════════════════

const gc = $('Global Config').first().json;
const a = $('Assert & Decide').first().json;
// Supabase sign endpoint returns { signedURL: "/object/sign/<bucket>/<path>?token=…" }.
const signed = $json.signedURL || ($json.body && $json.body.signedURL) || null;
const ttl = Number(gc.SIGNED_URL_TTL) || 86400;
const fullUrl = signed ? gc.SUPABASE_URL + '/storage/v1' + signed : null;

// Friendly download name: Supabase honours ?download=<name> (Content-Disposition),
// so Telegram shows «Позовна заява.pdf» instead of the raw case-id path.
const DOC_NAME = 'Позовна заява.pdf';

return [{ json: {
  _signed_url: fullUrl,
  _bot_doc_url: fullUrl ? fullUrl + '&download=' + encodeURIComponent(DOC_NAME) : null,
  _expires_at: new Date(Date.now() + ttl * 1000).toISOString(),
  _deliver: a._deliver === true,
  _user_id: a._user_id,
} }];
